<script setup>
import { computed, onMounted, reactive, ref } from 'vue'

const activeView = ref('overview')
const products = ref([])
const productsPageContent = ref([])
const categories = ref([])
const suppliers = ref([])
const purchaseOrders = ref([])
const saleOrders = ref([])
const notifications = ref([])
const productPage = reactive({ page: 0, size: 10, totalElements: 0, totalPages: 0 })
const purchasePage = reactive({ page: 0, size: 8, totalElements: 0, totalPages: 0 })
const salePage = reactive({ page: 0, size: 8, totalElements: 0, totalPages: 0 })
const inventoryTransactions = ref([])
const inventoryAdjustments = ref([])
const storeComparison = ref([])
const analytics = ref(null)
const weeklyReport = ref(null)
const replenishment = ref(null)
const analyticsLoading = ref(false)
const weeklyReportLoading = ref(false)
const replenishmentLoading = ref(false)
const sessionToken = ref(localStorage.getItem('merchant_session') || '')
const currentUser = ref(null)
const loginLoading = ref(false)
const loginError = ref('')
const authNotice = ref(false)
const authMode = ref('login')
const loginForm = reactive({ username: 'admin', password: 'admin123' })
const registerForm = reactive({ username: '', password: '', confirmPassword: '', recoveryCode: '' })
const recoverForm = reactive({ username: '', recoveryCode: '', newPassword: '', confirmPassword: '' })
const operationLogs = ref([])
const users = ref([])
const usersLoading = ref(false)
const userForm = reactive({ username: '', password: '', role: 'CLERK' })
const passwordForm = reactive({ currentPassword: '', newPassword: '', confirmPassword: '' })
const recoveryCodeForm = reactive({ currentPassword: '', recoveryCode: '', confirmRecoveryCode: '' })
const salesReport = ref(null)
const reportLoading = ref(false)
const today = new Date()
const localDate = (date) => `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}-${String(date.getDate()).padStart(2, '0')}`
const reportDates = reactive({ from: localDate(new Date(today.getFullYear(), today.getMonth(), today.getDate() - 29)), to: localDate(today) })
const loading = ref(false)
const purchaseLoading = ref(false)
const saleLoading = ref(false)
const error = ref('')
const search = ref('')
const category = ref('')
const productStatus = ref('')
const productLowStock = ref(false)
const purchaseFilters = reactive({ keyword: '', status: '', from: '', to: '' })
const saleFilters = reactive({ keyword: '', status: '', from: '', to: '' })
const supplierSearch = ref('')
const modalOpen = ref(false)
const supplierModalOpen = ref(false)
const categoryModalOpen = ref(false)
const adjustmentModalOpen = ref(false)
const importModalOpen = ref(false)
const importInput = ref(null)
const importing = ref(false)
const importResult = ref(null)
const storeMenuOpen = ref(false)
const storeModalOpen = ref(false)
const notificationOpen = ref(false)
const userMenuOpen = ref(false)
const refreshState = ref('idle')
const dataUpdatedAt = ref(null)
const editingId = ref(null)
const editingSupplierId = ref(null)
const editingCategoryId = ref(null)
const toast = ref('')
const form = reactive({ sku: '', name: '', category: '', purchasePrice: '', sellingPrice: '', stockWarningLine: 10 })
const supplierForm = reactive({ name: '', contact: '', phone: '', address: '' })
const categoryForm = reactive({ name: '', enabled: true })
const adjustmentForm = reactive({ productId: '', actualStock: '', reasonType: 'STOCKTAKE', remark: '' })
const storeForm = reactive({ name: '', address: '' })
const defaultStores = [{ id: 'tingting', name: '婷婷便利店', address: '当前经营门店' }]
const storedStores = (() => {
  try {
    const value = JSON.parse(localStorage.getItem('merchant_stores') || 'null')
    return Array.isArray(value) && value.length ? value : defaultStores
  } catch (err) {
    return defaultStores
  }
})()
const stores = ref(storedStores)
const currentStoreId = ref(localStorage.getItem('merchant_current_store') || '1')
const purchaseForm = reactive({ supplierId: '', remark: '', items: [{ productId: '', quantity: 1, unitPrice: '' }] })
const saleForm = reactive({ remark: '', items: [{ productId: '', quantity: 1 }] })

const pageTitle = computed(() => ({ overview: '经营概览', products: '商品管理', suppliers: '供应商管理', purchases: '采购入库', sales: '销售出库', inventory: '库存流水', analytics: '经营分析', storeComparison: '门店对比', reports: '经营报表', users: '用户与安全', operationLogs: '操作日志' }[activeView.value] || '经营概览'))
const isAdmin = computed(() => currentUser.value?.role === 'ADMIN')
const globalLoading = computed(() => loginLoading.value || loading.value || purchaseLoading.value || saleLoading.value || analyticsLoading.value || weeklyReportLoading.value || replenishmentLoading.value || usersLoading.value || reportLoading.value || importing.value)
const currentDateText = computed(() => new Intl.DateTimeFormat('zh-CN', { year: 'numeric', month: 'long', day: 'numeric', weekday: 'long' }).format(new Date()))
const maxDailySales = computed(() => Math.max(1, ...(analytics.value?.dailySales || []).map((item) => Number(item.salesAmount))))
const filteredSuppliers = computed(() => suppliers.value.filter((supplier) => !supplierSearch.value.trim() || supplier.name.toLowerCase().includes(supplierSearch.value.trim().toLowerCase())))
const activeSuppliers = computed(() => suppliers.value.filter((supplier) => supplier.enabled))
const totalStock = computed(() => products.value.reduce((total, product) => total + Number(product.stock || 0), 0))
const lowStockCount = computed(() => products.value.filter((product) => product.enabled && product.stock <= product.stockWarningLine).length)
const purchaseTotal = computed(() => purchaseForm.items.reduce((total, item) => total + Number(item.quantity || 0) * Number(item.unitPrice || 0), 0))
const saleTotal = computed(() => saleForm.items.reduce((total, item) => { const product = products.value.find((p) => p.id === Number(item.productId)); return total + Number(item.quantity || 0) * Number(product?.sellingPrice || 0) }, 0))
const currentStore = computed(() => stores.value.find((store) => String(store.id) === String(currentStoreId.value)) || stores.value[0])
const enabledCategories = computed(() => categories.value.filter((item) => item.enabled))
const comparisonTotals = computed(() => storeComparison.value.reduce((totals, item) => ({ salesAmount: totals.salesAmount + Number(item.salesAmount || 0), grossProfit: totals.grossProfit + Number(item.grossProfit || 0), orderCount: totals.orderCount + Number(item.orderCount || 0), lowStockCount: totals.lowStockCount + Number(item.lowStockCount || 0) }), { salesAmount: 0, grossProfit: 0, orderCount: 0, lowStockCount: 0 }))
const maxStoreSales = computed(() => Math.max(1, ...storeComparison.value.map((item) => Number(item.salesAmount || 0))))
const unreadNotificationCount = computed(() => notifications.value.filter((item) => !item.read).length)
const lastUpdatedLabel = computed(() => dataUpdatedAt.value ? `数据更新于 ${dataUpdatedAt.value.toLocaleTimeString('zh-CN', { hour: '2-digit', minute: '2-digit' })}` : '数据更新于刚刚')
function money(value) { return `¥ ${Number(value || 0).toFixed(2)}` }
function showToast(message) { toast.value = message; window.clearTimeout(showToast.timer); showToast.timer = window.setTimeout(() => { toast.value = '' }, 2600) }
function displayError(err, fallback = '操作失败，请稍后重试') { const message = err?.message || fallback; error.value = message; showToast(message); return message }
async function request(url, options = {}) { const headers = new Headers(options.headers || {}); if (sessionToken.value) headers.set('X-Session-Token', sessionToken.value); if (currentStoreId.value) headers.set('X-Store-Id', currentStoreId.value); let response; try { response = await fetch(url, { ...options, headers }) } catch (err) { throw new Error('后端服务暂时不可用，请检查服务是否已启动') } const data = await response.json().catch(() => ({})); if (response.status === 401) { currentUser.value = null; sessionToken.value = ''; localStorage.removeItem('merchant_session'); throw new Error(data.message || '登录已过期，请重新登录') } if (response.status === 403) throw new Error(data.message || '没有执行该操作的权限'); if (response.status === 404) throw new Error(data.message || '数据不存在或已被删除'); if (!response.ok) throw new Error(data.message || (response.status >= 500 ? '服务器暂时无法完成请求，请稍后重试' : '请求参数不合法')); return data }
async function login() { loginLoading.value = true; loginError.value = ''; authNotice.value = false; try { const data = await request('/api/auth/login', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(loginForm) }); sessionToken.value = data.token; currentUser.value = data.user; localStorage.setItem('merchant_session', data.token); await loadStores(); await Promise.all([loadProducts(), loadCategories(), loadSuppliers(), loadAnalytics(), loadNotifications()]) } catch (err) { loginError.value = err.message } finally { loginLoading.value = false } }
function switchAuthMode(mode) { authMode.value = mode; loginError.value = ''; authNotice.value = false }
async function registerAccount() { loginError.value = ''; authNotice.value = false; if (registerForm.password !== registerForm.confirmPassword) { loginError.value = '两次输入的密码不一致'; return } loginLoading.value = true; try { await request('/api/auth/register', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ username: registerForm.username, password: registerForm.password, recoveryCode: registerForm.recoveryCode }) }); loginForm.username = registerForm.username.trim().toLowerCase(); loginForm.password = ''; Object.assign(registerForm, { username: '', password: '', confirmPassword: '', recoveryCode: '' }); authMode.value = 'login'; authNotice.value = true; loginError.value = '注册成功，请等待管理员审核并启用账号' } catch (err) { loginError.value = err.message } finally { loginLoading.value = false } }
async function recoverPassword() { loginError.value = ''; authNotice.value = false; if (recoverForm.newPassword !== recoverForm.confirmPassword) { loginError.value = '两次输入的新密码不一致'; return } loginLoading.value = true; try { await request('/api/auth/recover-password', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ username: recoverForm.username, recoveryCode: recoverForm.recoveryCode, newPassword: recoverForm.newPassword }) }); loginForm.username = recoverForm.username.trim().toLowerCase(); loginForm.password = ''; Object.assign(recoverForm, { username: '', recoveryCode: '', newPassword: '', confirmPassword: '' }); authMode.value = 'login'; authNotice.value = true; loginError.value = '密码已重置，请使用新密码登录' } catch (err) { loginError.value = err.message } finally { loginLoading.value = false } }
async function logout() { try { await request('/api/auth/logout', { method: 'POST' }) } catch (err) { /* clear local session if the server is unavailable */ } sessionToken.value = ''; currentUser.value = null; localStorage.removeItem('merchant_session'); activeView.value = 'overview' }
async function loadCurrentUser() { if (!sessionToken.value) return; try { currentUser.value = await request('/api/auth/me') } catch (err) { currentUser.value = null } }
async function loadStores() { try { const data = await request('/api/stores'); if (data.length) { stores.value = data; if (!data.some(store => String(store.id) === String(currentStoreId.value))) currentStoreId.value = String(data[0].id); localStorage.setItem('merchant_current_store', currentStoreId.value) } } catch (err) { displayError(err) } }

async function loadProducts() { loading.value = true; try { products.value = await request('/api/products') } catch (err) { displayError(err) } finally { loading.value = false } }
function queryString(values) { const params = new URLSearchParams(); Object.entries(values).forEach(([key, value]) => { if (value !== '' && value !== null && value !== undefined && value !== false) params.set(key, value) }); return params.toString() }
async function loadProductPage(reset = false) { if (reset) productPage.page = 0; loading.value = true; try { const data = await request(`/api/products/page?${queryString({ page: productPage.page, size: productPage.size, keyword: search.value.trim(), category: category.value, enabled: productStatus.value, lowStock: productLowStock.value })}`); productsPageContent.value = data.content; Object.assign(productPage, { page: data.page, size: data.size, totalElements: data.totalElements, totalPages: data.totalPages }) } catch (err) { displayError(err) } finally { loading.value = false } }
async function loadCategories() { try { categories.value = await request('/api/categories') } catch (err) { displayError(err) } }
async function loadSuppliers() { try { suppliers.value = await request('/api/suppliers') } catch (err) { displayError(err) } }
async function loadPurchaseOrders(reset = false) { if (reset) purchasePage.page = 0; purchaseLoading.value = true; try { const data = await request(`/api/purchase-orders/page?${queryString({ page: purchasePage.page, size: purchasePage.size, ...purchaseFilters })}`); purchaseOrders.value = data.content; Object.assign(purchasePage, { page: data.page, size: data.size, totalElements: data.totalElements, totalPages: data.totalPages }) } catch (err) { displayError(err) } finally { purchaseLoading.value = false } }
async function loadSaleOrders(reset = false) { if (reset) salePage.page = 0; saleLoading.value = true; try { const data = await request(`/api/sale-orders/page?${queryString({ page: salePage.page, size: salePage.size, ...saleFilters })}`); saleOrders.value = data.content; Object.assign(salePage, { page: data.page, size: data.size, totalElements: data.totalElements, totalPages: data.totalPages }) } catch (err) { displayError(err) } finally { saleLoading.value = false } }
async function loadNotifications() { try { notifications.value = await request('/api/notifications') } catch (err) { displayError(err) } }
async function loadInventoryTransactions() { try { inventoryTransactions.value = await request('/api/inventory-transactions') } catch (err) { displayError(err) } }
async function loadInventoryAdjustments() { if (!isAdmin.value) return; try { inventoryAdjustments.value = await request('/api/inventory-adjustments') } catch (err) { displayError(err) } }
async function loadStoreComparison() { if (!isAdmin.value) return; try { storeComparison.value = await request('/api/analytics/store-comparison') } catch (err) { displayError(err) } }
async function loadAnalytics() { analyticsLoading.value = true; try { analytics.value = await request('/api/analytics/overview') } catch (err) { displayError(err) } finally { analyticsLoading.value = false } }
async function generateWeeklyReport() { weeklyReportLoading.value = true; error.value = ''; try { weeklyReport.value = await request('/api/analytics/weekly-report', { method: 'POST' }) } catch (err) { displayError(err) } finally { weeklyReportLoading.value = false } }
async function generateReplenishment() { replenishmentLoading.value = true; error.value = ''; try { replenishment.value = await request('/api/analytics/replenishment', { method: 'POST' }) } catch (err) { displayError(err) } finally { replenishmentLoading.value = false } }
async function loadOperationLogs() { try { operationLogs.value = await request('/api/operation-logs') } catch (err) { displayError(err) } }
async function loadUsers() { if (!isAdmin.value) return; usersLoading.value = true; try { users.value = await request('/api/users') } catch (err) { displayError(err) } finally { usersLoading.value = false } }
async function createUser() { try { await request('/api/users', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(userForm) }); Object.assign(userForm, { username: '', password: '', role: 'CLERK' }); showToast('用户已创建'); await loadUsers() } catch (err) { displayError(err) } }
async function toggleUser(user) { try { await request(`/api/users/${user.id}/status`, { method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ enabled: !user.enabled }) }); showToast(user.enabled ? '用户已停用' : '用户已启用'); await loadUsers() } catch (err) { displayError(err) } }
async function resetUserPassword(user) { const password = window.prompt(`为 ${user.username} 设置新密码（至少 6 位）`); if (!password) return; try { await request(`/api/users/${user.id}/reset-password`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ password }) }); showToast('密码已重置，该用户需要重新登录') } catch (err) { displayError(err) } }
async function changePassword() { error.value = ''; if (passwordForm.newPassword !== passwordForm.confirmPassword) { error.value = '两次输入的新密码不一致'; return } try { await request('/api/auth/change-password', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ currentPassword: passwordForm.currentPassword, newPassword: passwordForm.newPassword }) }); sessionToken.value = ''; currentUser.value = null; localStorage.removeItem('merchant_session'); Object.assign(passwordForm, { currentPassword: '', newPassword: '', confirmPassword: '' }); loginError.value = '密码修改成功，请使用新密码重新登录' } catch (err) { displayError(err) } }
async function saveRecoveryCode() { error.value = ''; if (recoveryCodeForm.recoveryCode !== recoveryCodeForm.confirmRecoveryCode) { error.value = '两次输入的找回码不一致'; return } try { await request('/api/auth/recovery-code', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ currentPassword: recoveryCodeForm.currentPassword, recoveryCode: recoveryCodeForm.recoveryCode }) }); Object.assign(recoveryCodeForm, { currentPassword: '', recoveryCode: '', confirmRecoveryCode: '' }); showToast('找回码已更新') } catch (err) { displayError(err) } }
async function loadSalesReport() { reportLoading.value = true; error.value = ''; try { salesReport.value = await request(`/api/reports/sales?from=${reportDates.from}&to=${reportDates.to}`) } catch (err) { displayError(err) } finally { reportLoading.value = false } }
async function exportSalesReport() { try { const response = await fetch(`/api/reports/sales/export?from=${reportDates.from}&to=${reportDates.to}`, { headers: { 'X-Session-Token': sessionToken.value, 'X-Store-Id': currentStoreId.value } }); if (!response.ok) throw new Error('报表导出失败'); const blob = await response.blob(); const url = URL.createObjectURL(blob); const link = document.createElement('a'); link.href = url; link.download = `sales-report-${reportDates.from}-${reportDates.to}.csv`; link.click(); URL.revokeObjectURL(url); showToast('销售报表已导出') } catch (err) { displayError(err) } }
async function downloadExcel(path, fallbackName, successMessage) { try { const response = await fetch(path, { headers: { 'X-Session-Token': sessionToken.value, 'X-Store-Id': currentStoreId.value } }); if (!response.ok) { const data = await response.json().catch(() => ({})); throw new Error(data.message || 'Excel 导出失败') } const blob = await response.blob(); const disposition = response.headers.get('Content-Disposition') || ''; const match = disposition.match(/filename\*=UTF-8''([^;]+)/i) || disposition.match(/filename="?([^";]+)"?/i); const filename = match ? decodeURIComponent(match[1]) : fallbackName; const url = URL.createObjectURL(blob); const link = document.createElement('a'); link.href = url; link.download = filename; document.body.appendChild(link); link.click(); link.remove(); URL.revokeObjectURL(url); showToast(successMessage) } catch (err) { displayError(err) } }
function downloadProductTemplate() { return downloadExcel('/api/data-transfer/products/template', 'product-import-template.xlsx', '商品导入模板已下载') }
function exportBusinessData(type) { const config = { products: ['products', '商品库存'], purchases: ['purchase-orders', '采购单'], sales: ['sale-orders', '销售单'], inventory: ['inventory-transactions', '库存流水'] }[type]; return downloadExcel(`/api/data-transfer/${type}/export`, `${config[0]}.xlsx`, `${config[1]}已导出`) }
function openProductImport() { importResult.value = null; if (importInput.value) importInput.value.value = ''; importInput.value?.click() }
async function importProducts(event) { const file = event.target.files?.[0]; if (!file) return; if (!file.name.toLowerCase().endsWith('.xlsx')) { displayError(new Error('请选择 .xlsx 格式的商品导入文件')); event.target.value = ''; return } importing.value = true; importResult.value = null; try { const body = new FormData(); body.append('file', file); importResult.value = await request('/api/data-transfer/products/import', { method: 'POST', body }); importModalOpen.value = true; showToast(`导入完成：成功 ${importResult.value.successCount} 条，失败 ${importResult.value.failureCount} 条`); await Promise.all([loadProducts(), loadProductPage(true), loadInventoryTransactions(), loadAnalytics(), loadNotifications()]) } catch (err) { displayError(err) } finally { importing.value = false; event.target.value = '' } }
function openCreate() { editingId.value = null; Object.assign(form, { sku: '', name: '', category: '', purchasePrice: '', sellingPrice: '', stockWarningLine: 10 }); error.value = ''; modalOpen.value = true }
function openEdit(product) { editingId.value = product.id; Object.assign(form, { sku: product.sku, name: product.name, category: product.category || '', purchasePrice: product.purchasePrice, sellingPrice: product.sellingPrice, stockWarningLine: product.stockWarningLine }); error.value = ''; modalOpen.value = true }
async function saveProduct() { try { const id = editingId.value; await request(id ? `/api/products/${id}` : '/api/products', { method: id ? 'PUT' : 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ ...form, purchasePrice: Number(form.purchasePrice), sellingPrice: Number(form.sellingPrice), stockWarningLine: Number(form.stockWarningLine), enabled: true }) }); modalOpen.value = false; showToast(id ? '商品已更新' : '商品已添加'); await Promise.all([loadProducts(), loadProductPage(), loadNotifications()]) } catch (err) { displayError(err) } }
async function disableProduct(product) { if (!window.confirm(`确定停用“${product.name}”吗？`)) return; try { await request(`/api/products/${product.id}`, { method: 'DELETE' }); showToast('商品已停用'); await Promise.all([loadProducts(), loadProductPage(), loadNotifications()]) } catch (err) { showToast(err.message) } }

function openCategoryManager() { editingCategoryId.value = null; Object.assign(categoryForm, { name: '', enabled: true }); categoryModalOpen.value = true }
function editCategory(item) { editingCategoryId.value = item.id; Object.assign(categoryForm, { name: item.name, enabled: item.enabled }) }
function resetCategoryForm() { editingCategoryId.value = null; Object.assign(categoryForm, { name: '', enabled: true }) }
async function saveCategory() { try { const id = editingCategoryId.value; await request(id ? `/api/categories/${id}` : '/api/categories', { method: id ? 'PUT' : 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(categoryForm) }); showToast(id ? '分类已更新' : '分类已添加'); resetCategoryForm(); await loadCategories() } catch (err) { displayError(err) } }
async function disableCategory(item) { if (!window.confirm(`确定停用分类“${item.name}”吗？已有商品仍保留该分类。`)) return; try { await request(`/api/categories/${item.id}`, { method: 'DELETE' }); showToast('分类已停用'); await loadCategories() } catch (err) { displayError(err) } }

function openSupplierCreate() { editingSupplierId.value = null; Object.assign(supplierForm, { name: '', contact: '', phone: '', address: '' }); error.value = ''; supplierModalOpen.value = true }
function openSupplierEdit(supplier) { editingSupplierId.value = supplier.id; Object.assign(supplierForm, { name: supplier.name, contact: supplier.contact || '', phone: supplier.phone || '', address: supplier.address || '' }); error.value = ''; supplierModalOpen.value = true }
async function saveSupplier() { try { const id = editingSupplierId.value; await request(id ? `/api/suppliers/${id}` : '/api/suppliers', { method: id ? 'PUT' : 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ ...supplierForm, enabled: true }) }); supplierModalOpen.value = false; showToast(id ? '供应商已更新' : '供应商已添加'); await loadSuppliers() } catch (err) { displayError(err) } }
async function disableSupplier(supplier) { if (!window.confirm(`确定停用“${supplier.name}”吗？`)) return; try { await request(`/api/suppliers/${supplier.id}`, { method: 'DELETE' }); showToast('供应商已停用'); await loadSuppliers() } catch (err) { showToast(err.message) } }
function persistStores() { localStorage.setItem('merchant_stores', JSON.stringify(stores.value)) }
async function reloadStoreData() { const tasks = [loadProducts(), loadCategories(), loadSuppliers(), loadAnalytics(), loadNotifications()]; if (activeView.value === 'products') tasks.push(loadProductPage()); if (activeView.value === 'purchases') tasks.push(loadPurchaseOrders()); if (activeView.value === 'sales') tasks.push(loadSaleOrders()); if (activeView.value === 'inventory') tasks.push(loadInventoryTransactions(), loadInventoryAdjustments()); if (activeView.value === 'storeComparison') tasks.push(loadStoreComparison()); if (activeView.value === 'reports') tasks.push(loadSalesReport()); await Promise.all(tasks) }
async function refreshData() { if (refreshState.value === 'loading') return; refreshState.value = 'loading'; try { await reloadStoreData(); dataUpdatedAt.value = new Date(); showToast('当前门店数据已更新') } finally { refreshState.value = 'idle' } }
async function openNotification(item) { if (!item.read) { try { await request(`/api/notifications/${item.id}/read`, { method: 'PUT' }); item.read = true } catch (err) { displayError(err) } } notificationOpen.value = false; selectView(item.targetView) }
async function markAllNotificationsRead() { if (!unreadNotificationCount.value) return; try { await request('/api/notifications/read-all', { method: 'PUT' }); notifications.value.forEach((item) => { item.read = true }); showToast('通知已全部标记为已读') } catch (err) { displayError(err) } }
function toggleUserMenu() { userMenuOpen.value = !userMenuOpen.value; notificationOpen.value = false }
function toggleNotifications() { notificationOpen.value = !notificationOpen.value; userMenuOpen.value = false; if (notificationOpen.value) loadNotifications() }
async function selectStore(storeId) { currentStoreId.value = String(storeId); localStorage.setItem('merchant_current_store', currentStoreId.value); storeMenuOpen.value = false; error.value = ''; weeklyReport.value = null; replenishment.value = null; salesReport.value = null; await reloadStoreData(); showToast(`已切换至${currentStore.value.name}`) }
function openStoreCreate() { storeMenuOpen.value = false; Object.assign(storeForm, { name: '', address: '' }); storeModalOpen.value = true }
async function saveStore() { const name = storeForm.name.trim(); if (!name) return; try { const store = await request('/api/stores', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ name, address: storeForm.address.trim() }) }); stores.value.push(store); currentStoreId.value = String(store.id); localStorage.setItem('merchant_current_store', currentStoreId.value); storeModalOpen.value = false; showToast(`已添加并切换至${name}`); await Promise.all([loadProducts(), loadCategories(), loadSuppliers(), loadAnalytics(), loadNotifications()]) } catch (err) { displayError(err) } }

function addPurchaseItem() { purchaseForm.items.push({ productId: '', quantity: 1, unitPrice: '' }) }
function resetProductFilters() { search.value = ''; category.value = ''; productStatus.value = ''; productLowStock.value = false; loadProductPage(true) }
function resetPurchaseFilters() { Object.assign(purchaseFilters, { keyword: '', status: '', from: '', to: '' }); loadPurchaseOrders(true) }
function resetSaleFilters() { Object.assign(saleFilters, { keyword: '', status: '', from: '', to: '' }); loadSaleOrders(true) }
function changeProductPage(delta) { const next = productPage.page + delta; if (next >= 0 && next < productPage.totalPages) { productPage.page = next; loadProductPage() } }
function changePurchasePage(delta) { const next = purchasePage.page + delta; if (next >= 0 && next < purchasePage.totalPages) { purchasePage.page = next; loadPurchaseOrders() } }
function changeSalePage(delta) { const next = salePage.page + delta; if (next >= 0 && next < salePage.totalPages) { salePage.page = next; loadSaleOrders() } }
function removePurchaseItem(index) { if (purchaseForm.items.length > 1) purchaseForm.items.splice(index, 1) }
function resetPurchaseForm() { Object.assign(purchaseForm, { supplierId: '', remark: '', items: [{ productId: '', quantity: 1, unitPrice: '' }] }) }
async function createPurchase() { try { const created = await request('/api/purchase-orders', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ supplierId: Number(purchaseForm.supplierId), remark: purchaseForm.remark, items: purchaseForm.items.map((item) => ({ productId: Number(item.productId), quantity: Number(item.quantity), unitPrice: Number(item.unitPrice) })) }) }); await request(`/api/purchase-orders/${created.id}/receive`, { method: 'POST' }); resetPurchaseForm(); showToast('采购单已入库，库存已更新'); await Promise.all([loadProducts(), loadPurchaseOrders(), loadNotifications()]) } catch (err) { displayError(err) } }
async function receivePurchase(order) { try { await request(`/api/purchase-orders/${order.id}/receive`, { method: 'POST' }); showToast('采购单已入库'); await Promise.all([loadProducts(), loadPurchaseOrders(), loadNotifications()]) } catch (err) { showToast(err.message) } }
async function cancelPurchase(order) { if (!window.confirm(`确定取消采购单 ${order.orderNo} 吗？`)) return; try { await request(`/api/purchase-orders/${order.id}/cancel`, { method: 'POST' }); showToast('采购单已取消'); await Promise.all([loadPurchaseOrders(), loadNotifications()]) } catch (err) { showToast(err.message) } }
function purchaseStatus(status) { return ({ DRAFT: '草稿', RECEIVED: '已入库', CANCELLED: '已取消' })[status] || status }
function addSaleItem() { saleForm.items.push({ productId: '', quantity: 1 }) }
function removeSaleItem(index) { if (saleForm.items.length > 1) saleForm.items.splice(index, 1) }
function resetSaleForm() { Object.assign(saleForm, { remark: '', items: [{ productId: '', quantity: 1 }] }) }
async function createSale() { try { await request('/api/sale-orders', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ remark: saleForm.remark, items: saleForm.items.map((item) => ({ productId: Number(item.productId), quantity: Number(item.quantity) })) }) }); resetSaleForm(); showToast('销售已完成，库存已扣减'); await Promise.all([loadProducts(), loadSaleOrders(), loadNotifications()]) } catch (err) { displayError(err); await loadNotifications() } }
function inventoryType(type) { return ({ PURCHASE: '采购入库', SALE: '销售出库', ADJUSTMENT: '库存调整' })[type] || type }
function inventoryDelta(record) { return Number(record.afterStock) - Number(record.beforeStock) }
function adjustmentReason(reason) { return ({ STOCKTAKE: '盘点修正', SURPLUS: '盘盈', LOSS: '盘亏', DAMAGE: '破损', EXPIRED: '过期', OTHER: '其他' })[reason] || reason }
function openAdjustment(product = null) { Object.assign(adjustmentForm, { productId: product?.id || '', actualStock: product?.stock ?? '', reasonType: 'STOCKTAKE', remark: '' }); adjustmentModalOpen.value = true }
async function saveAdjustment() { try { await request('/api/inventory-adjustments', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ productId: Number(adjustmentForm.productId), actualStock: Number(adjustmentForm.actualStock), reasonType: adjustmentForm.reasonType, remark: adjustmentForm.remark }) }); adjustmentModalOpen.value = false; showToast('库存盘点已保存，并生成库存流水'); await Promise.all([loadProducts(), loadInventoryTransactions(), loadInventoryAdjustments(), loadAnalytics(), loadNotifications()]) } catch (err) { displayError(err) } }
function selectView(view) { activeView.value = view; error.value = ''; if (view === 'overview') loadAnalytics(); if (view === 'products') { loadProducts(); loadProductPage(); loadCategories() } if (view === 'suppliers') loadSuppliers(); if (view === 'purchases') { loadProducts(); loadSuppliers(); loadPurchaseOrders() } if (view === 'sales') { loadProducts(); loadSaleOrders() } if (view === 'inventory') { loadProducts(); loadInventoryTransactions(); loadInventoryAdjustments() } if (view === 'analytics') loadAnalytics(); if (view === 'storeComparison') loadStoreComparison(); if (view === 'reports') loadSalesReport(); if (view === 'users') loadUsers(); if (view === 'operationLogs') loadOperationLogs() }
onMounted(async () => { await loadCurrentUser(); if (currentUser.value) { await loadStores(); loadProducts(); loadCategories(); loadSuppliers(); loadAnalytics(); loadNotifications() } })
</script>

<template>
  <div v-if="globalLoading" class="global-loading" role="status" aria-live="polite"><span></span><small>正在处理...</small></div>
  <section v-if="!currentUser" class="login-screen"><div class="login-panel auth-panel"><div class="brand login-brand"><span class="brand-mark">M</span><div><strong>Merchant OS</strong><small>经营辅助决策系统</small></div></div><div class="auth-tabs" role="tablist"><button type="button" :class="{ active: authMode === 'login' }" @click="switchAuthMode('login')">登录</button><button type="button" :class="{ active: authMode === 'register' }" @click="switchAuthMode('register')">注册</button><button type="button" :class="{ active: authMode === 'recover' }" @click="switchAuthMode('recover')">找回密码</button></div><template v-if="authMode === 'login'"><p class="eyebrow">安全登录</p><h1>欢迎回来</h1><p class="login-copy">登录后管理商品、库存、销售和经营分析。</p><form @submit.prevent="login"><label>用户名<input v-model="loginForm.username" autocomplete="username" required /></label><label>密码<input v-model="loginForm.password" type="password" autocomplete="current-password" required /></label><p v-if="loginError" :class="['form-error', 'auth-message', { success: authNotice }]">{{ loginError }}</p><button class="primary full-button" type="submit" :disabled="loginLoading">{{ loginLoading ? '登录中...' : '登录系统' }}</button></form><small class="login-hint">演示账号：admin / admin123　店员：clerk / clerk123</small></template><template v-else-if="authMode === 'register'"><p class="eyebrow">创建店员账号</p><h1>注册账号</h1><p class="login-copy">注册后由管理员审核，启用后即可登录。</p><form @submit.prevent="registerAccount"><label>用户名<input v-model="registerForm.username" required minlength="3" maxlength="32" pattern="[A-Za-z0-9_]+" autocomplete="username" placeholder="字母、数字或下划线" /></label><label>登录密码<input v-model="registerForm.password" type="password" required minlength="6" maxlength="64" autocomplete="new-password" /></label><label>确认密码<input v-model="registerForm.confirmPassword" type="password" required minlength="6" maxlength="64" autocomplete="new-password" /></label><label>找回码<input v-model="registerForm.recoveryCode" type="password" required minlength="8" maxlength="64" autocomplete="off" placeholder="至少 8 位且不要与密码相同" /></label><small class="recovery-note">请妥善保存找回码，遗失后需联系管理员。</small><p v-if="loginError" :class="['form-error', 'auth-message', { success: authNotice }]">{{ loginError }}</p><button class="primary full-button" type="submit" :disabled="loginLoading">{{ loginLoading ? '注册中...' : '创建账号' }}</button></form></template><template v-else><p class="eyebrow">账户恢复</p><h1>找回密码</h1><p class="login-copy">验证注册时设置的找回码后重置密码。</p><form @submit.prevent="recoverPassword"><label>用户名<input v-model="recoverForm.username" required autocomplete="username" /></label><label>找回码<input v-model="recoverForm.recoveryCode" type="password" required minlength="8" maxlength="64" autocomplete="off" /></label><label>新密码<input v-model="recoverForm.newPassword" type="password" required minlength="6" maxlength="64" autocomplete="new-password" /></label><label>确认新密码<input v-model="recoverForm.confirmPassword" type="password" required minlength="6" maxlength="64" autocomplete="new-password" /></label><p v-if="loginError" :class="['form-error', 'auth-message', { success: authNotice }]">{{ loginError }}</p><button class="primary full-button" type="submit" :disabled="loginLoading">{{ loginLoading ? '重置中...' : '重置密码' }}</button></form></template></div></section>
  <div v-else class="app-shell">
    <aside class="sidebar">
      <div class="brand"><span class="brand-mark">M</span><div><strong>Merchant OS</strong><small>经营辅助决策系统</small></div></div>
      <div class="store-switch" @keydown.esc="storeMenuOpen = false"><small>当前门店</small><button class="store-trigger" type="button" :aria-expanded="storeMenuOpen" aria-haspopup="menu" @click="storeMenuOpen = !storeMenuOpen"><span class="store-name">{{ currentStore.name }}</span><span class="store-chevron" :class="{ open: storeMenuOpen }">⌄</span></button><div v-if="storeMenuOpen" class="store-menu" role="menu"><button v-for="store in stores" :key="store.id" class="store-option" :class="{ selected: String(store.id) === String(currentStoreId) }" type="button" role="menuitem" @click="selectStore(store.id)"><span><strong>{{ store.name }}</strong><small>{{ store.address || '门店' }}</small></span><b v-if="String(store.id) === String(currentStoreId)">✓</b></button><div class="store-menu-divider"></div><button class="store-add" type="button" @click="openStoreCreate"><span>＋</span> 添加店铺</button></div></div>
      <nav class="nav-list" aria-label="主导航">
        <button class="nav-item" :class="{ active: activeView === 'overview' }" @click="selectView('overview')"><span>⌂</span>经营概览</button>
        <button class="nav-item" :class="{ active: activeView === 'products' }" @click="selectView('products')"><span>▦</span>商品管理</button>
        <button class="nav-item" :class="{ active: activeView === 'suppliers' }" @click="selectView('suppliers')"><span>♧</span>供应商管理</button>
        <button class="nav-item" :class="{ active: activeView === 'purchases' }" @click="selectView('purchases')"><span>↗</span>采购入库</button>
        <button class="nav-item" :class="{ active: activeView === 'sales' }" @click="selectView('sales')"><span>↘</span>销售出库</button>
        <button class="nav-item" :class="{ active: activeView === 'inventory' }" @click="selectView('inventory')"><span>⇄</span>库存流水</button>
        <button class="nav-item" :class="{ active: activeView === 'analytics' }" @click="selectView('analytics')"><span>✦</span>经营分析</button>
        <button v-if="isAdmin" class="nav-item" :class="{ active: activeView === 'storeComparison' }" @click="selectView('storeComparison')"><span>▥</span>门店对比</button>
        <button class="nav-item" :class="{ active: activeView === 'reports' }" @click="selectView('reports')"><span>▥</span>经营报表</button>
        <button v-if="isAdmin" class="nav-item" :class="{ active: activeView === 'operationLogs' }" @click="selectView('operationLogs')"><span>▤</span>操作日志</button>
      </nav>
      <div class="sidebar-bottom"><div class="ai-note"><span>✦</span><div><strong>AI 助手</strong><small>数据积累后开启智能分析</small></div></div><button class="nav-item muted" :class="{ active: activeView === 'users' }" type="button" @click="selectView('users')"><span>⚙</span>用户与安全</button><div class="user-mini"><span class="avatar">{{ currentUser.username.slice(0, 1).toUpperCase() }}</span><div><strong>{{ currentUser.username }}</strong><small>{{ currentUser.role === 'ADMIN' ? '管理员' : '店员' }}</small></div><button class="logout-button" type="button" title="退出登录" @click="logout">退出</button></div></div>
    </aside>
    <main class="main-content">
      <header class="topbar">
        <div class="breadcrumb"><span>{{ currentStore.name }}</span><b>/</b><strong>{{ pageTitle }}</strong></div>
        <div class="top-actions">
          <button class="sync-status" type="button" :disabled="refreshState === 'loading'" @click="refreshData"><span class="sync-dot" :class="refreshState"></span>{{ refreshState === 'loading' ? '正在更新...' : lastUpdatedLabel }}</button>
          <div class="top-popover-wrap">
            <button class="bell" type="button" aria-label="通知" :aria-expanded="notificationOpen" @click="toggleNotifications">♧<i v-if="unreadNotificationCount"></i><b v-if="unreadNotificationCount" class="bell-count">{{ unreadNotificationCount > 9 ? '9+' : unreadNotificationCount }}</b></button>
            <div v-if="notificationOpen" class="top-popover notification-popover">
              <div class="popover-head"><span><strong>通知中心</strong><small>{{ unreadNotificationCount }} 条未读 · 共 {{ notifications.length }} 条</small></span><button v-if="unreadNotificationCount" type="button" class="mark-all" @click="markAllNotificationsRead">全部已读</button></div>
              <div class="notification-list">
                <button v-for="item in notifications" :key="item.id" class="notification-item" :class="{ unread: !item.read }" type="button" @click="openNotification(item)">
                  <span class="notification-icon" :class="item.type === 'OUT_OF_STOCK' || item.type === 'SALE_ALERT' ? 'warning' : item.type === 'PURCHASE_COMPLETED' ? 'success' : 'info'">{{ item.type === 'OUT_OF_STOCK' || item.type === 'SALE_ALERT' ? '!' : item.type === 'PURCHASE_COMPLETED' ? '✓' : 'i' }}</span>
                  <span><strong>{{ item.title }}</strong><small>{{ item.message }}</small><time>{{ new Date(item.createdAt).toLocaleString('zh-CN') }}</time></span><b>›</b>
                </button>
                <div v-if="!notifications.length" class="empty notification-empty"><span>✓</span><strong>暂无通知</strong><small>当前门店没有待处理提醒。</small></div>
              </div>
            </div>
          </div>
          <div class="top-popover-wrap"><button class="avatar avatar-button" type="button" aria-label="用户菜单" :aria-expanded="userMenuOpen" @click="toggleUserMenu">刘</button><div v-if="userMenuOpen" class="top-popover user-popover"><div class="popover-user"><span class="avatar">刘</span><span><strong>刘先生</strong><small>{{ currentUser.role === 'ADMIN' ? '管理员' : '店员' }}</small></span></div><button type="button" @click="userMenuOpen = false; selectView('users')">⚙ 用户与安全</button><button type="button" @click="userMenuOpen = false; logout()">↪ 退出登录</button></div></div>
        </div>
      </header>

      <section v-if="activeView === 'overview'" class="content">
        <div class="heading"><div><p class="eyebrow">{{ currentDateText }}</p><h1>你好，刘先生</h1><p>这里是当前经营状态，先看看哪些地方需要你的注意。</p></div><button class="primary" type="button" @click="openCreate">＋ 添加商品</button></div>
        <div class="metrics"><article><div class="metric-label">近30天销售额 <span class="metric-icon revenue">↗</span></div><strong>{{ money(analytics?.salesAmount) }}</strong><small>{{ analytics?.orderCount || 0 }} 笔销售单</small></article><article><div class="metric-label">近30天毛利 <span class="metric-icon profit">◇</span></div><strong>{{ money(analytics?.grossProfit) }}</strong><small>毛利率 {{ analytics?.grossMargin || 0 }}%</small></article><article><div class="metric-label">在售库存 <span class="metric-icon inventory">▱</span></div><strong>{{ analytics?.totalStock ?? totalStock }}</strong><small>当前可用库存总量</small></article><article><div class="metric-label">库存预警 <span class="metric-icon alert">!</span></div><strong>{{ analytics?.lowStockCount ?? lowStockCount }}</strong><small><b class="danger">需要及时关注</b></small></article></div>
        <div class="two-columns"><article class="panel sales"><div class="panel-head"><div><h2>销售趋势</h2><small>真实近 7 天销售额</small></div><button class="link" type="button" @click="selectView('analytics')">查看分析</button></div><div v-if="analytics?.dailySales?.length" class="trend-list overview-trend"><div v-for="day in analytics.dailySales" :key="day.date" class="trend-row"><time>{{ day.date.slice(5) }}</time><div class="trend-bar"><i :style="{ width: `${Math.max(1, Number(day.salesAmount) / maxDailySales * 100)}%` }"></i></div><b>{{ money(day.salesAmount) }}</b></div></div><div v-else class="loading-row">正在读取经营数据...</div></article><article class="panel attention"><div class="panel-head"><div><h2>今日关注</h2><small>需要你处理的事项</small></div><button class="link" type="button" @click="selectView('purchases')">查看采购</button></div><div class="attention-list"><div><span class="attention-icon red">!</span><p><strong>库存不足</strong><small>有 <b>{{ analytics?.lowStockCount ?? lowStockCount }}</b> 个商品低于预警线</small></p><button type="button" @click="selectView('products')">→</button></div><div><span class="attention-icon amber">↺</span><p><strong>采购入库</strong><small>创建采购单并更新库存</small></p><button type="button" @click="selectView('purchases')">→</button></div><div><span class="attention-icon teal">✦</span><p><strong>经营建议</strong><small>根据真实经营数据生成建议</small></p><button type="button" @click="selectView('analytics')">→</button></div></div></article></div>
        <article class="panel shortcuts"><div class="panel-head"><div><h2>快捷入口</h2><small>把常用操作放在手边</small></div></div><div class="shortcut-grid"><button type="button" @click="openCreate"><span class="shortcut-icon green">＋</span><span><strong>添加商品</strong><small>维护商品资料</small></span><b>→</b></button><button type="button" @click="selectView('purchases')"><span class="shortcut-icon blue">↗</span><span><strong>新建采购单</strong><small>记录商品入库</small></span><b>→</b></button><button type="button" @click="selectView('sales')"><span class="shortcut-icon orange">↘</span><span><strong>登记销售</strong><small>销售完成后自动出库</small></span><b>→</b></button></div></article>
      </section>

      <section v-else-if="activeView === 'products'" class="content">
        <div class="heading"><div><p class="eyebrow">基础资料</p><h1>商品管理</h1><p>统一维护商品价格、库存和预警线。</p></div><div class="heading-actions data-actions"><input ref="importInput" class="file-input" type="file" accept=".xlsx" @change="importProducts" /><button class="secondary" type="button" @click="exportBusinessData('products')">⇩ 导出 Excel</button><button v-if="isAdmin" class="secondary" type="button" @click="downloadProductTemplate">▧ 下载模板</button><button v-if="isAdmin" class="secondary" type="button" :disabled="importing" @click="openProductImport">⇧ {{ importing ? '导入中...' : '批量导入' }}</button><button v-if="isAdmin" class="secondary" type="button" @click="openCategoryManager">▦ 分类管理</button><button class="primary" type="button" @click="openCreate">＋ 添加商品</button></div></div>
        <div class="toolbar filter-toolbar">
          <label class="search"><span>⌕</span><input v-model="search" type="search" placeholder="搜索商品名称或编码" @keyup.enter="loadProductPage(true)" /></label>
          <select v-model="category"><option value="">全部分类</option><option v-for="item in categories" :key="item.id" :value="item.name">{{ item.name }}{{ item.enabled ? '' : '（已停用）' }}</option></select>
          <select v-model="productStatus"><option value="">全部状态</option><option value="true">在售</option><option value="false">已停用</option></select>
          <label class="check-filter"><input v-model="productLowStock" type="checkbox" /> 仅看库存预警</label>
          <button class="primary compact-button" type="button" @click="loadProductPage(true)">查询</button><button class="secondary compact-button" type="button" @click="resetProductFilters">重置</button>
        </div>
        <article class="panel product-panel"><div class="table-meta"><span>共 <b>{{ productPage.totalElements }}</b> 件商品</span><small v-if="loading">正在读取数据...</small><small v-else>库存数据实时同步</small></div><div v-if="error" class="inline-error">{{ error }}</div><div class="table-scroll"><table v-if="productsPageContent.length"><thead><tr><th>商品</th><th>分类</th><th>售价</th><th>库存</th><th>预警线</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="product in productsPageContent" :key="product.id"><td><strong>{{ product.name }}</strong><small>{{ product.sku }}</small></td><td>{{ product.category || '未分类' }}</td><td>{{ money(product.sellingPrice) }}</td><td :class="product.stock <= product.stockWarningLine ? 'low' : 'ok'">{{ product.stock }}<span v-if="product.stock <= product.stockWarningLine"> · 需补货</span></td><td>{{ product.stockWarningLine }}</td><td><em :class="product.enabled ? 'status' : 'status off'">{{ product.enabled ? '在售' : '已停用' }}</em></td><td><button class="table-action" type="button" @click="openEdit(product)">编辑</button><button v-if="isAdmin" class="table-action" type="button" @click="openAdjustment(product)">盘点</button><button v-if="product.enabled && isAdmin" class="table-action danger" type="button" @click="disableProduct(product)">停用</button></td></tr></tbody></table><div v-else class="empty"><span>▦</span><strong>没有符合条件的商品</strong><small>调整筛选条件，或添加第一件商品。</small><button class="primary" type="button" @click="openCreate">添加商品</button></div></div><div class="pagination"><span>第 {{ productPage.totalPages ? productPage.page + 1 : 0 }} / {{ productPage.totalPages }} 页</span><div><button class="secondary" type="button" :disabled="productPage.page <= 0" @click="changeProductPage(-1)">上一页</button><button class="secondary" type="button" :disabled="productPage.page + 1 >= productPage.totalPages" @click="changeProductPage(1)">下一页</button></div></div></article>
      </section>

      <section v-else-if="activeView === 'suppliers'" class="content"><div class="heading"><div><p class="eyebrow">采购基础资料</p><h1>供应商管理</h1><p>维护合作供应商，采购入库时可直接选择。</p></div><button class="primary" type="button" @click="openSupplierCreate">＋ 添加供应商</button></div><div class="toolbar"><label class="search"><span>⌕</span><input v-model="supplierSearch" type="search" placeholder="搜索供应商名称" /></label><button class="secondary" type="button" @click="loadSuppliers">↻ 刷新</button></div><article class="panel product-panel"><div class="table-meta"><span>共 <b>{{ filteredSuppliers.length }}</b> 家供应商</span><small>停用供应商不会影响历史采购单</small></div><div class="table-scroll"><table v-if="filteredSuppliers.length"><thead><tr><th>供应商</th><th>联系人</th><th>联系电话</th><th>地址</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="supplier in filteredSuppliers" :key="supplier.id"><td><strong>{{ supplier.name }}</strong><small>更新于 {{ supplier.updatedAt?.slice(0, 10) || '-' }}</small></td><td>{{ supplier.contact || '-' }}</td><td>{{ supplier.phone || '-' }}</td><td>{{ supplier.address || '-' }}</td><td><em :class="supplier.enabled ? 'status' : 'status off'">{{ supplier.enabled ? '合作中' : '已停用' }}</em></td><td><button class="table-action" type="button" @click="openSupplierEdit(supplier)">编辑</button><button v-if="supplier.enabled && isAdmin" class="table-action danger" type="button" @click="disableSupplier(supplier)">停用</button></td></tr></tbody></table><div v-else class="empty"><span>♧</span><strong>还没有供应商</strong><small>添加供应商后即可创建采购单。</small><button class="primary" type="button" @click="openSupplierCreate">添加供应商</button></div></div></article></section>

      <section v-else-if="activeView === 'purchases'" class="content">
        <div class="heading"><div><p class="eyebrow">库存业务</p><h1>采购入库</h1><p>创建采购单并确认入库，系统会自动增加商品库存。</p></div><button class="secondary" type="button" @click="exportBusinessData('purchases')">⇩ 导出 Excel</button></div>
        <div class="purchase-layout"><article class="panel purchase-form"><div class="panel-head"><div><h2>新建采购单</h2><small>入库确认后将生成库存流水</small></div><span class="purchase-total">合计 {{ money(purchaseTotal) }}</span></div><label>供应商<select v-model="purchaseForm.supplierId"><option value="">请选择供应商</option><option v-for="supplier in activeSuppliers" :key="supplier.id" :value="supplier.id">{{ supplier.name }}</option></select></label><div class="purchase-items"><div class="purchase-items-head"><span>采购商品</span><button type="button" class="link" @click="addPurchaseItem">＋ 添加商品</button></div><div v-for="(item, index) in purchaseForm.items" :key="index" class="purchase-item"><select v-model="item.productId"><option value="">选择商品</option><option v-for="product in products.filter((p) => p.enabled)" :key="product.id" :value="product.id">{{ product.name }} · {{ product.sku }}</option></select><input v-model="item.quantity" type="number" min="1" placeholder="数量" /><input v-model="item.unitPrice" type="number" min="0" step="0.01" placeholder="采购价" /><button type="button" class="remove-item" @click="removePurchaseItem(index)">×</button></div></div><label>备注<textarea v-model="purchaseForm.remark" rows="2" placeholder="可填写供应商批次或到货说明"></textarea></label><div v-if="error" class="form-error">{{ error }}</div><button class="primary full-button" type="button" :disabled="!purchaseForm.supplierId || purchaseForm.items.some((item) => !item.productId || !item.quantity || item.unitPrice === '')" @click="createPurchase">确认采购并入库</button></article>
          <article class="panel orders-panel"><div class="panel-head"><div><h2>采购记录</h2><small>支持单号、供应商、日期和状态筛选</small></div><button class="secondary small-button" type="button" @click="loadPurchaseOrders">↻</button></div><div class="order-filters"><input v-model="purchaseFilters.keyword" placeholder="采购单号或供应商" @keyup.enter="loadPurchaseOrders(true)" /><select v-model="purchaseFilters.status"><option value="">全部状态</option><option value="DRAFT">草稿</option><option value="RECEIVED">已入库</option><option value="CANCELLED">已取消</option></select><input v-model="purchaseFilters.from" type="date" /><input v-model="purchaseFilters.to" type="date" /><button class="primary compact-button" type="button" @click="loadPurchaseOrders(true)">查询</button><button class="secondary compact-button" type="button" @click="resetPurchaseFilters">重置</button></div><div v-if="purchaseLoading" class="loading-row">正在读取...</div><div v-else-if="purchaseOrders.length" class="order-list"><div v-for="order in purchaseOrders" :key="order.id" class="order-row"><div><strong>{{ order.orderNo }}</strong><small>{{ order.supplierName }} · {{ order.items.length }} 件商品 · {{ new Date(order.createdAt).toLocaleDateString('zh-CN') }}</small></div><div class="order-right"><span>{{ money(order.totalAmount) }}</span><em :class="order.status === 'RECEIVED' ? 'status' : order.status === 'CANCELLED' ? 'status off' : 'status pending'">{{ purchaseStatus(order.status) }}</em><button v-if="order.status === 'DRAFT'" type="button" class="table-action" @click="receivePurchase(order)">确认入库</button><button v-if="order.status === 'DRAFT' && isAdmin" type="button" class="table-action danger" @click="cancelPurchase(order)">取消</button></div></div></div><div v-else class="empty compact"><span>↗</span><strong>暂无符合条件的采购记录</strong><small>调整筛选条件或创建采购单。</small></div><div class="pagination"><span>共 {{ purchasePage.totalElements }} 条 · 第 {{ purchasePage.totalPages ? purchasePage.page + 1 : 0 }} / {{ purchasePage.totalPages }} 页</span><div><button class="secondary" type="button" :disabled="purchasePage.page <= 0" @click="changePurchasePage(-1)">上一页</button><button class="secondary" type="button" :disabled="purchasePage.page + 1 >= purchasePage.totalPages" @click="changePurchasePage(1)">下一页</button></div></div></article></div>
      </section>

      <section v-else-if="activeView === 'sales'" class="content">
        <div class="heading"><div><p class="eyebrow">销售业务</p><h1>销售出库</h1><p>登记销售后立即校验并扣减库存，同时生成库存流水。</p></div><button class="secondary" type="button" @click="exportBusinessData('sales')">⇩ 导出 Excel</button></div>
        <div class="purchase-layout"><article class="panel purchase-form"><div class="panel-head"><div><h2>登记销售</h2><small>售价取自当前商品售价</small></div><span class="purchase-total">合计 {{ money(saleTotal) }}</span></div><div class="purchase-items"><div class="purchase-items-head"><span>销售商品</span><button type="button" class="link" @click="addSaleItem">＋ 添加商品</button></div><div v-for="(item, index) in saleForm.items" :key="index" class="sale-item"><select v-model="item.productId"><option value="">选择商品</option><option v-for="product in products.filter((p) => p.enabled && p.stock > 0)" :key="product.id" :value="product.id">{{ product.name }} · 库存 {{ product.stock }} · {{ money(product.sellingPrice) }}</option></select><input v-model="item.quantity" type="number" min="1" placeholder="数量" /><button type="button" class="remove-item" @click="removeSaleItem(index)">×</button></div></div><label>备注<textarea v-model="saleForm.remark" rows="2" placeholder="可填写支付方式或销售说明"></textarea></label><div v-if="error" class="form-error">{{ error }}</div><button class="primary full-button" type="button" :disabled="saleForm.items.some((item) => !item.productId || !item.quantity)" @click="createSale">确认销售并出库</button></article>
          <article class="panel orders-panel"><div class="panel-head"><div><h2>销售记录</h2><small>支持单号、日期和状态筛选</small></div><button class="secondary small-button" type="button" @click="loadSaleOrders">↻</button></div><div class="order-filters"><input v-model="saleFilters.keyword" placeholder="销售单号" @keyup.enter="loadSaleOrders(true)" /><select v-model="saleFilters.status"><option value="">全部状态</option><option value="COMPLETED">已完成</option></select><input v-model="saleFilters.from" type="date" /><input v-model="saleFilters.to" type="date" /><button class="primary compact-button" type="button" @click="loadSaleOrders(true)">查询</button><button class="secondary compact-button" type="button" @click="resetSaleFilters">重置</button></div><div v-if="saleLoading" class="loading-row">正在读取...</div><div v-else-if="saleOrders.length" class="order-list"><div v-for="order in saleOrders" :key="order.id" class="order-row"><div><strong>{{ order.orderNo }}</strong><small>{{ order.items.map((item) => `${item.productName} × ${item.quantity}`).join('、') }} · {{ new Date(order.createdAt).toLocaleDateString('zh-CN') }}</small></div><div class="order-right"><span>{{ money(order.totalAmount) }}</span><em class="status">已完成</em></div></div></div><div v-else class="empty compact"><span>↘</span><strong>暂无符合条件的销售记录</strong><small>调整筛选条件或登记第一笔销售。</small></div><div class="pagination"><span>共 {{ salePage.totalElements }} 条 · 第 {{ salePage.totalPages ? salePage.page + 1 : 0 }} / {{ salePage.totalPages }} 页</span><div><button class="secondary" type="button" :disabled="salePage.page <= 0" @click="changeSalePage(-1)">上一页</button><button class="secondary" type="button" :disabled="salePage.page + 1 >= salePage.totalPages" @click="changeSalePage(1)">下一页</button></div></div></article></div>
      </section>

      <section v-else-if="activeView === 'analytics'" class="content">
        <div class="heading"><div><p class="eyebrow">数据驱动经营</p><h1>经营分析</h1><p>查看真实经营指标，生成每周总结和补货建议。</p></div><button class="primary" type="button" :disabled="analyticsLoading" @click="loadAnalytics">{{ analyticsLoading ? '正在刷新...' : '↻ 刷新分析' }}</button></div>
        <div v-if="analytics" class="metrics analytics-metrics"><article><div class="metric-label">近30天销售额</div><strong>{{ money(analytics.salesAmount) }}</strong><small>{{ analytics.orderCount }} 笔销售单</small></article><article><div class="metric-label">毛利额</div><strong>{{ money(analytics.grossProfit) }}</strong><small>毛利率 {{ analytics.grossMargin }}%</small></article><article><div class="metric-label">在售库存</div><strong>{{ analytics.totalStock }}</strong><small>{{ analytics.lowStockCount }} 件低于预警线</small></article><article><div class="metric-label">智能分析</div><strong>{{ weeklyReport?.source === 'AI' || replenishment?.source === 'AI' ? 'AI' : '规则' }}</strong><small>{{ weeklyReport || replenishment ? '已生成最新结果' : '等待生成分析' }}</small></article></div>
        <div v-if="error" class="inline-error">{{ error }}</div>
        <div v-if="analytics" class="two-columns analytics-columns">
          <article class="panel analytics-panel"><div class="panel-head"><div><h2>近7天销售趋势</h2><small>按日汇总销售额</small></div></div><div class="trend-list"><div v-for="day in analytics.dailySales" :key="day.date" class="trend-row"><time>{{ day.date.slice(5) }}</time><div class="trend-bar"><i :style="{ width: `${Math.min(100, Number(day.salesAmount) / Math.max(1, ...analytics.dailySales.map((item) => Number(item.salesAmount))) * 100)}%` }"></i></div><b>{{ money(day.salesAmount) }}</b></div></div></article>
          <article class="panel analytics-panel weekly-panel"><div class="panel-head"><div><h2>经营周报</h2><small>{{ weeklyReport ? `${weeklyReport.from} 至 ${weeklyReport.to}` : '最近 7 天与前 7 天对比' }}</small></div><button class="secondary small-button" type="button" :disabled="weeklyReportLoading" @click="generateWeeklyReport">{{ weeklyReportLoading ? '生成中...' : '生成周报' }}</button></div><div v-if="weeklyReport" class="advice-body"><div class="analysis-source-line"><span class="advice-source">{{ weeklyReport.source === 'AI' ? 'AI 周报' : '规则周报' }}</span><small>{{ weeklyReport.statusMessage }}</small></div><p>{{ weeklyReport.summary }}</p><div class="weekly-numbers"><span><b>{{ money(weeklyReport.salesAmount) }}</b><small>销售额</small></span><span><b>{{ weeklyReport.orderCount }}</b><small>订单</small></span><span><b>{{ weeklyReport.productQuantity }}</b><small>销量</small></span></div><h3>经营亮点</h3><ul><li v-for="item in weeklyReport.highlights" :key="item">{{ item }}</li></ul><h3>下周行动</h3><ol><li v-for="item in weeklyReport.actions" :key="item">{{ item }}</li></ol></div><div v-else class="empty compact"><span>▥</span><strong>尚未生成周报</strong><small>点击生成本周经营总结。</small></div></article>
        </div>
        <article v-if="analytics" class="panel analytics-panel replenishment-panel"><div class="panel-head"><div><h2>智能补货建议</h2><small>近30天销量、库存预警线与 14 天覆盖周期</small></div><button class="secondary small-button" type="button" :disabled="replenishmentLoading" @click="generateReplenishment">{{ replenishmentLoading ? '计算中...' : '计算补货' }}</button></div><div v-if="replenishment" class="replenishment-body"><div class="analysis-source-line"><span class="advice-source">{{ replenishment.source === 'AI' ? 'AI 总结' : '规则分析' }}</span><small>{{ replenishment.statusMessage }}</small></div><div class="replenishment-summary"><p>{{ replenishment.summary }}</p><strong>{{ money(replenishment.estimatedCost) }}<small>预计采购成本</small></strong></div><div v-if="replenishment.items.length" class="table-scroll"><table class="replenishment-table"><thead><tr><th>商品</th><th>当前库存</th><th>近30天销量</th><th>建议补货</th><th>预计成本</th><th>依据</th></tr></thead><tbody><tr v-for="item in replenishment.items" :key="item.productId"><td><strong>{{ item.productName }}</strong><small>{{ item.sku }}</small></td><td>{{ item.currentStock }}</td><td>{{ item.salesQuantity30Days }}</td><td class="ok">{{ item.recommendedQuantity }}</td><td>{{ money(item.estimatedCost) }}</td><td>{{ item.reason }}</td></tr></tbody></table></div><div v-else class="empty compact"><span>✓</span><strong>当前无需补货</strong><small>库存可覆盖现阶段销售需求。</small></div></div><div v-else class="empty compact"><span>↺</span><strong>尚未计算补货建议</strong><small>系统只生成建议，不会自动创建采购单。</small></div></article>
        <div v-if="analytics" class="two-columns analytics-columns"><article class="panel analytics-panel"><div class="panel-head"><div><h2>销售排行</h2><small>按销售额排序</small></div></div><div class="rank-list"><div v-for="(item, index) in analytics.topProducts" :key="item.productId" class="rank-row"><b>{{ index + 1 }}</b><span><strong>{{ item.productName }}</strong><small>{{ item.sku }} · 销量 {{ item.quantity }}</small></span><em>{{ money(item.salesAmount) }}</em></div><div v-if="!analytics.topProducts.length" class="empty compact"><strong>暂无销售数据</strong></div></div></article><article class="panel analytics-panel"><div class="panel-head"><div><h2>库存预警</h2><small>需要优先关注的商品</small></div></div><div class="rank-list"><div v-for="item in analytics.lowStockProducts" :key="item.productId" class="rank-row"><span><strong>{{ item.productName }}</strong><small>{{ item.sku }} · 预警线 {{ item.warningLine }}</small></span><em class="low">库存 {{ item.stock }}</em></div><div v-if="!analytics.lowStockProducts.length" class="empty compact"><strong>暂无库存预警</strong></div></div></article></div>
      </section>

      <section v-else-if="activeView === 'storeComparison'" class="content"><div class="heading"><div><p class="eyebrow">多门店经营</p><h1>门店经营对比</h1><p>统一比较各门店近 30 天销售、毛利和库存风险。</p></div><button class="secondary" type="button" @click="loadStoreComparison">↻ 刷新数据</button></div><div class="metrics comparison-metrics"><article><div class="metric-label">全部门店销售额<span class="metric-icon revenue">¥</span></div><strong>{{ money(comparisonTotals.salesAmount) }}</strong><small>近 30 天合计</small></article><article><div class="metric-label">全部门店毛利<span class="metric-icon profit">↑</span></div><strong>{{ money(comparisonTotals.grossProfit) }}</strong><small>销售额减销售成本</small></article><article><div class="metric-label">订单总数<span class="metric-icon inventory">▤</span></div><strong>{{ comparisonTotals.orderCount }}</strong><small>{{ storeComparison.length }} 家营业门店</small></article><article><div class="metric-label">库存预警<span class="metric-icon alert">!</span></div><strong>{{ comparisonTotals.lowStockCount }}</strong><small>各店低库存商品合计</small></article></div><article class="panel comparison-panel"><div class="table-meta"><span>门店排行与经营指标</span><small>当前门店以浅绿色标记</small></div><div class="table-scroll"><table v-if="storeComparison.length" class="comparison-table"><thead><tr><th>门店</th><th>销售额</th><th>销售对比</th><th>订单</th><th>毛利</th><th>毛利率</th><th>库存</th><th>预警</th></tr></thead><tbody><tr v-for="store in storeComparison" :key="store.storeId" :class="{ 'current-store-row': String(store.storeId) === String(currentStoreId) }"><td><strong>{{ store.storeName }}</strong><small>{{ store.address || '暂无地址' }}</small></td><td class="ok">{{ money(store.salesAmount) }}</td><td><div class="comparison-bar"><i :style="{ width: `${Math.max(2, Number(store.salesAmount) / maxStoreSales * 100)}%` }"></i></div></td><td>{{ store.orderCount }}</td><td>{{ money(store.grossProfit) }}</td><td>{{ Number(store.grossMargin).toFixed(2) }}%</td><td>{{ store.totalStock }}</td><td :class="store.lowStockCount ? 'low' : 'ok'">{{ store.lowStockCount }}</td></tr></tbody></table><div v-else class="empty"><span>▥</span><strong>暂无门店对比数据</strong><small>添加门店并录入经营数据后即可比较。</small></div></div></article></section>

      <section v-else-if="activeView === 'reports'" class="content"><div class="heading"><div><p class="eyebrow">经营数据归档</p><h1>销售报表</h1><p>按日期查看销售、成本、毛利和商品销量，并导出 CSV。</p></div><button class="primary" type="button" :disabled="!salesReport" @click="exportSalesReport">↓ 导出 CSV</button></div><div class="report-filter"><label>开始日期<input v-model="reportDates.from" type="date" :max="reportDates.to" /></label><label>结束日期<input v-model="reportDates.to" type="date" :min="reportDates.from" /></label><button class="secondary" type="button" :disabled="reportLoading" @click="loadSalesReport">{{ reportLoading ? '查询中...' : '查询报表' }}</button></div><div v-if="error" class="inline-error">{{ error }}</div><template v-if="salesReport"><div class="metrics report-metrics"><article><div class="metric-label">销售额</div><strong>{{ money(salesReport.salesAmount) }}</strong><small>{{ salesReport.orderCount }} 笔订单</small></article><article><div class="metric-label">销售数量</div><strong>{{ salesReport.productQuantity }}</strong><small>商品累计销量</small></article><article><div class="metric-label">销售成本</div><strong>{{ money(salesReport.totalCost) }}</strong><small>按销售时成本计算</small></article><article><div class="metric-label">毛利</div><strong>{{ money(salesReport.grossProfit) }}</strong><small>毛利率 {{ salesReport.grossMargin }}%</small></article></div><article class="panel product-panel"><div class="table-meta"><span>商品销售明细</span><small>{{ salesReport.from }} 至 {{ salesReport.to }}</small></div><div class="table-scroll"><table v-if="salesReport.products.length"><thead><tr><th>商品</th><th>编码</th><th>销量</th><th>销售额</th></tr></thead><tbody><tr v-for="item in salesReport.products" :key="item.productId"><td><strong>{{ item.productName }}</strong></td><td>{{ item.sku }}</td><td>{{ item.quantity }}</td><td class="ok">{{ money(item.salesAmount) }}</td></tr></tbody></table><div v-else class="empty"><span>▥</span><strong>所选日期暂无销售数据</strong><small>调整日期范围后重新查询。</small></div></div></article></template></section>

      <section v-else-if="activeView === 'users'" class="content"><div class="heading"><div><p class="eyebrow">账户安全</p><h1>用户与安全</h1><p>修改当前密码；管理员可以维护系统登录账号。</p></div></div><div class="two-columns security-columns"><form class="panel security-form" @submit.prevent="changePassword"><div class="panel-head"><div><h2>修改密码</h2><small>修改成功后需要重新登录</small></div></div><label>当前密码<input v-model="passwordForm.currentPassword" type="password" required autocomplete="current-password" /></label><label>新密码<input v-model="passwordForm.newPassword" type="password" minlength="6" maxlength="64" required autocomplete="new-password" /></label><label>确认新密码<input v-model="passwordForm.confirmPassword" type="password" minlength="6" maxlength="64" required autocomplete="new-password" /></label><button class="primary full-button" type="submit">更新密码</button></form><form v-if="isAdmin" class="panel security-form" autocomplete="off" @submit.prevent="createUser"><div class="panel-head"><div><h2>添加用户</h2><small>创建管理员或店员账号</small></div></div><label>用户名<input v-model="userForm.username" required maxlength="64" autocomplete="off" /></label><label>初始密码<input v-model="userForm.password" type="password" minlength="6" maxlength="64" required autocomplete="new-password" /></label><label>角色<select v-model="userForm.role"><option value="CLERK">店员</option><option value="ADMIN">管理员</option></select></label><button class="primary full-button" type="submit">创建用户</button></form><form class="panel security-form" autocomplete="off" @submit.prevent="saveRecoveryCode"><div class="panel-head"><div><h2>设置找回码</h2><small>用于登录页的密码找回</small></div></div><label>当前密码<input v-model="recoveryCodeForm.currentPassword" type="password" required autocomplete="current-password" /></label><label>新找回码<input v-model="recoveryCodeForm.recoveryCode" type="password" minlength="8" maxlength="64" required autocomplete="off" /></label><label>确认找回码<input v-model="recoveryCodeForm.confirmRecoveryCode" type="password" minlength="8" maxlength="64" required autocomplete="off" /></label><button class="primary full-button" type="submit">保存找回码</button></form></div><div v-if="error" class="inline-error">{{ error }}</div><article v-if="isAdmin" class="panel product-panel"><div class="table-meta"><span>系统用户 <b>{{ users.length }}</b> 人</span><small v-if="usersLoading">正在读取...</small><small v-else>停用后现有会话立即失效</small></div><div class="table-scroll"><table><thead><tr><th>用户名</th><th>角色</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="user in users" :key="user.id"><td><strong>{{ user.username }}</strong><small v-if="user.id === currentUser.id">当前账号</small></td><td>{{ user.role === 'ADMIN' ? '管理员' : '店员' }}</td><td><em :class="user.enabled ? 'status' : 'status off'">{{ user.enabled ? '正常' : '已停用' }}</em></td><td><button class="table-action" type="button" @click="resetUserPassword(user)">重置密码</button><button v-if="user.id !== currentUser.id" class="table-action danger" type="button" @click="toggleUser(user)">{{ user.enabled ? '停用' : '启用' }}</button></td></tr></tbody></table></div></article></section>

      <section v-else-if="activeView === 'operationLogs'" class="content"><div class="heading"><div><p class="eyebrow">安全审计</p><h1>操作日志</h1><p>记录登录后的业务写操作，便于追溯责任和排查问题。</p></div><button class="secondary" type="button" @click="loadOperationLogs">↻ 刷新</button></div><article class="panel product-panel"><div class="table-meta"><span>最近 <b>{{ operationLogs.length }}</b> 条记录</span><small>最多展示 100 条</small></div><div class="table-scroll"><table v-if="operationLogs.length"><thead><tr><th>时间</th><th>操作人</th><th>方法</th><th>路径</th><th>状态</th></tr></thead><tbody><tr v-for="log in operationLogs" :key="log.id"><td>{{ new Date(log.createdAt).toLocaleString('zh-CN') }}</td><td><strong>{{ log.username }}</strong></td><td>{{ log.method }}</td><td>{{ log.path }}</td><td><em class="status">{{ log.status }}</em></td></tr></tbody></table><div v-else class="empty"><span>▤</span><strong>暂无操作日志</strong><small>完成新增、采购或销售后会自动记录。</small></div></div></article></section>
      <section v-else-if="activeView === 'inventory'" class="content"><div class="heading"><div><p class="eyebrow">库存审计</p><h1>库存流水与盘点</h1><p>每一次采购、销售和盘点调整都会留下可追溯记录。</p></div><div class="heading-actions"><button class="secondary" type="button" @click="exportBusinessData('inventory')">⇩ 导出 Excel</button><button class="secondary" type="button" @click="loadInventoryTransactions">↻ 刷新</button><button v-if="isAdmin" class="primary" type="button" @click="openAdjustment()">＋ 库存盘点</button></div></div><article class="panel product-panel"><div class="table-meta"><span>共 <b>{{ inventoryTransactions.length }}</b> 条流水</span><small>按发生时间倒序展示</small></div><div class="table-scroll"><table v-if="inventoryTransactions.length"><thead><tr><th>时间</th><th>商品</th><th>类型</th><th>变化数量</th><th>变化前</th><th>变化后</th><th>关联单号 ID</th></tr></thead><tbody><tr v-for="record in inventoryTransactions" :key="record.id"><td>{{ new Date(record.createdAt).toLocaleString('zh-CN') }}</td><td><strong>{{ record.productName }}</strong><small>{{ record.sku }}</small></td><td><em :class="inventoryDelta(record) < 0 ? 'flow-type out' : 'flow-type in'">{{ inventoryType(record.type) }}</em></td><td :class="inventoryDelta(record) < 0 ? 'low' : 'ok'">{{ inventoryDelta(record) > 0 ? '+' : '' }}{{ inventoryDelta(record) }}</td><td>{{ record.beforeStock }}</td><td>{{ record.afterStock }}</td><td>{{ record.referenceType }} #{{ record.referenceId }}</td></tr></tbody></table><div v-else class="empty"><span>⇄</span><strong>暂无库存流水</strong><small>完成采购入库、销售或盘点后会自动生成记录。</small></div></div></article><article v-if="isAdmin" class="panel product-panel adjustment-history"><div class="table-meta"><span>盘点调整记录 <b>{{ inventoryAdjustments.length }}</b> 条</span><small>记录实际库存、差异原因与备注</small></div><div class="table-scroll"><table v-if="inventoryAdjustments.length"><thead><tr><th>时间</th><th>商品</th><th>原因</th><th>系统库存</th><th>实际库存</th><th>差异</th><th>备注</th></tr></thead><tbody><tr v-for="item in inventoryAdjustments" :key="item.id"><td>{{ new Date(item.createdAt).toLocaleString('zh-CN') }}</td><td><strong>{{ item.productName }}</strong><small>{{ item.sku }}</small></td><td>{{ adjustmentReason(item.reasonType) }}</td><td>{{ item.beforeStock }}</td><td>{{ item.actualStock }}</td><td :class="item.quantityDifference < 0 ? 'low' : 'ok'">{{ item.quantityDifference > 0 ? '+' : '' }}{{ item.quantityDifference }}</td><td>{{ item.remark || '—' }}</td></tr></tbody></table><div v-else class="empty compact"><span>✓</span><strong>还没有盘点调整</strong><small>库存数量准确时无需产生调整记录。</small></div></div></article></section>
    </main>
  </div>

  <div v-if="modalOpen" class="modal-backdrop" @click.self="modalOpen = false"><form class="modal" @submit.prevent="saveProduct"><div class="modal-head"><div><h2>{{ editingId ? '编辑商品' : '添加商品' }}</h2><small>填写商品的基础信息</small></div><button class="close" type="button" @click="modalOpen = false">×</button></div><div class="form-grid"><label>商品编码<input v-model="form.sku" required maxlength="64" placeholder="例如 SKU-001" /></label><label>商品名称<input v-model="form.name" required maxlength="128" placeholder="例如 矿泉水" /></label><label>商品分类<select v-model="form.category"><option value="">请选择分类</option><option v-for="item in categories" :key="item.id" :value="item.name" :disabled="!item.enabled">{{ item.name }}{{ item.enabled ? '' : '（已停用）' }}</option></select></label><label>采购价<input v-model="form.purchasePrice" required min="0" step="0.01" type="number" placeholder="0.00" /></label><label>销售价<input v-model="form.sellingPrice" required min="0" step="0.01" type="number" placeholder="0.00" /></label><label>库存预警线<input v-model="form.stockWarningLine" required min="0" step="1" type="number" /></label></div><p class="stock-hint">库存由采购入库、销售出库和库存调整产生</p><div v-if="error" class="form-error">{{ error }}</div><div class="modal-actions"><button class="secondary" type="button" @click="modalOpen = false">取消</button><button class="primary" type="submit">{{ editingId ? '保存修改' : '保存商品' }}</button></div></form></div>
  <div v-if="importModalOpen && importResult" class="modal-backdrop" @click.self="importModalOpen = false"><div class="modal import-result-modal"><div class="modal-head"><div><h2>商品导入结果</h2><small>合法商品已写入当前门店，初始库存已生成库存流水</small></div><button class="close" type="button" @click="importModalOpen = false">×</button></div><div class="import-summary"><span><b>{{ importResult.totalRows }}</b> 数据行</span><span class="ok"><b>{{ importResult.successCount }}</b> 导入成功</span><span :class="importResult.failureCount ? 'low' : 'ok'"><b>{{ importResult.failureCount }}</b> 导入失败</span></div><div v-if="importResult.errors.length" class="import-errors"><div class="table-meta"><span>错误行明细</span><small>修正后可再次导入</small></div><div class="table-scroll"><table><thead><tr><th>Excel 行号</th><th>商品编码</th><th>错误原因</th></tr></thead><tbody><tr v-for="item in importResult.errors" :key="`${item.row}-${item.sku}`"><td>{{ item.row }}</td><td>{{ item.sku || '—' }}</td><td class="low">{{ item.message }}</td></tr></tbody></table></div></div><div v-else class="empty compact"><span>✓</span><strong>全部商品导入成功</strong><small>商品与初始库存已同步到当前门店。</small></div><div class="modal-actions"><button class="secondary" type="button" @click="downloadProductTemplate">再次下载模板</button><button class="primary" type="button" @click="importModalOpen = false">完成</button></div></div></div>
  <div v-if="supplierModalOpen" class="modal-backdrop" @click.self="supplierModalOpen = false"><form class="modal small-modal" @submit.prevent="saveSupplier"><div class="modal-head"><div><h2>{{ editingSupplierId ? '编辑供应商' : '添加供应商' }}</h2><small>填写供应商联系信息</small></div><button class="close" type="button" @click="supplierModalOpen = false">×</button></div><div class="form-grid"><label>供应商名称<input v-model="supplierForm.name" required maxlength="128" placeholder="例如 鲜达配送中心" /></label><label>联系人<input v-model="supplierForm.contact" placeholder="联系人姓名" /></label><label>联系电话<input v-model="supplierForm.phone" placeholder="手机或座机" /></label><label>地址<input v-model="supplierForm.address" placeholder="配送地址" /></label></div><div v-if="error" class="form-error">{{ error }}</div><div class="modal-actions"><button class="secondary" type="button" @click="supplierModalOpen = false">取消</button><button class="primary" type="submit">保存供应商</button></div></form></div>
  <div v-if="categoryModalOpen" class="modal-backdrop" @click.self="categoryModalOpen = false"><div class="modal category-modal"><div class="modal-head"><div><h2>商品分类管理</h2><small>分类按门店独立维护，停用后不能再分配给新商品</small></div><button class="close" type="button" @click="categoryModalOpen = false">×</button></div><form class="category-form" @submit.prevent="saveCategory"><input v-model="categoryForm.name" required maxlength="64" placeholder="输入分类名称" /><label><input v-model="categoryForm.enabled" type="checkbox" /> 启用</label><button class="primary" type="submit">{{ editingCategoryId ? '保存修改' : '添加分类' }}</button><button v-if="editingCategoryId" class="secondary" type="button" @click="resetCategoryForm">取消编辑</button></form><div class="category-list"><div v-for="item in categories" :key="item.id" class="category-row"><span><strong>{{ item.name }}</strong><small>{{ item.enabled ? '正常使用' : '已停用' }}</small></span><div><button class="table-action" type="button" @click="editCategory(item)">编辑</button><button v-if="item.enabled" class="table-action danger" type="button" @click="disableCategory(item)">停用</button></div></div></div></div></div>
  <div v-if="adjustmentModalOpen" class="modal-backdrop" @click.self="adjustmentModalOpen = false"><form class="modal small-modal" @submit.prevent="saveAdjustment"><div class="modal-head"><div><h2>库存盘点调整</h2><small>保存后会更新商品库存并自动生成库存流水</small></div><button class="close" type="button" @click="adjustmentModalOpen = false">×</button></div><div class="form-grid"><label>盘点商品<select v-model="adjustmentForm.productId" required><option value="">请选择商品</option><option v-for="product in products.filter(item => item.enabled)" :key="product.id" :value="product.id">{{ product.name }}（系统库存 {{ product.stock }}）</option></select></label><label>实际库存<input v-model="adjustmentForm.actualStock" required min="0" step="1" type="number" /></label><label>调整原因<select v-model="adjustmentForm.reasonType"><option value="STOCKTAKE">盘点修正</option><option value="SURPLUS">盘盈</option><option value="LOSS">盘亏</option><option value="DAMAGE">破损</option><option value="EXPIRED">过期</option><option value="OTHER">其他</option></select></label><label>备注<input v-model="adjustmentForm.remark" maxlength="255" placeholder="可填写盘点批次或具体原因" /></label></div><div v-if="adjustmentForm.productId" class="adjustment-preview"><span>系统库存 <b>{{ products.find(item => item.id === Number(adjustmentForm.productId))?.stock ?? 0 }}</b></span><span>盘点差异 <b :class="Number(adjustmentForm.actualStock) - Number(products.find(item => item.id === Number(adjustmentForm.productId))?.stock || 0) < 0 ? 'low' : 'ok'">{{ Number(adjustmentForm.actualStock) - Number(products.find(item => item.id === Number(adjustmentForm.productId))?.stock || 0) > 0 ? '+' : '' }}{{ Number(adjustmentForm.actualStock) - Number(products.find(item => item.id === Number(adjustmentForm.productId))?.stock || 0) }}</b></span></div><div v-if="error" class="form-error">{{ error }}</div><div class="modal-actions"><button class="secondary" type="button" @click="adjustmentModalOpen = false">取消</button><button class="primary" type="submit">确认调整库存</button></div></form></div>
  <div v-if="storeModalOpen" class="modal-backdrop" @click.self="storeModalOpen = false"><form class="modal small-modal" @submit.prevent="saveStore"><div class="modal-head"><div><h2>添加店铺</h2><small>添加后可从当前门店菜单切换</small></div><button class="close" type="button" aria-label="关闭" title="关闭" @click="storeModalOpen = false">×</button></div><div class="form-grid"><label>店铺名称<input v-model="storeForm.name" required maxlength="64" placeholder="例如 婷婷二店" /></label><label>店铺备注<input v-model="storeForm.address" maxlength="128" placeholder="例如 城南店" /></label></div><div class="modal-actions"><button class="secondary" type="button" @click="storeModalOpen = false">取消</button><button class="primary" type="submit">保存店铺</button></div></form></div>
  <transition name="toast"><div v-if="toast" class="toast">{{ toast }}</div></transition>
</template>

